-- Skills rework 2026-10-25: merge Lore of Ages+Faiths -> Lore, Wildlore+Wayfinding -> Wildcraft; rename 8 skills.
-- Idempotent: old names no longer match once applied. Skill text in descriptions is word-bounded; 'Mending' is not replaced in text (rune/spell/plain uses).
BEGIN;
CREATE OR REPLACE FUNCTION pg_temp.sk_map(arr text[]) RETURNS text[] LANGUAGE sql IMMUTABLE AS $$
  SELECT CASE WHEN arr IS NULL THEN NULL ELSE coalesce(array_agg(s ORDER BY o), '{}') END FROM (SELECT DISTINCT ON (s) s, o FROM (SELECT CASE s WHEN 'Lore of Ages' THEN 'Lore' WHEN 'Faiths' THEN 'Lore' WHEN 'Wildlore' THEN 'Wildcraft' WHEN 'Wayfinding' THEN 'Wildcraft' WHEN 'Tumbling' THEN 'Agility' WHEN 'Reading People' THEN 'Insight' WHEN 'Searching' THEN 'Investigation' WHEN 'Watchfulness' THEN 'Awareness' WHEN 'Mending' THEN 'Healing' WHEN 'Showcraft' THEN 'Performance' WHEN 'Quick Hands' THEN 'Sleight' WHEN 'Shadowing' THEN 'Stealth' ELSE s END AS s, o FROM unnest(arr) WITH ORDINALITY u(s, o)) m ORDER BY s, o) d
$$;
UPDATE classes SET skill_options = pg_temp.sk_map(skill_options), skill_fixed = pg_temp.sk_map(skill_fixed) WHERE skill_options IS DISTINCT FROM pg_temp.sk_map(skill_options) OR skill_fixed IS DISTINCT FROM pg_temp.sk_map(skill_fixed);
UPDATE characters SET skill_proficiencies = pg_temp.sk_map(skill_proficiencies) WHERE skill_proficiencies IS DISTINCT FROM pg_temp.sk_map(skill_proficiencies);
UPDATE race_lineage_bonuses SET skill = (pg_temp.sk_map(ARRAY[skill]))[1] WHERE skill IS DISTINCT FROM (pg_temp.sk_map(ARRAY[skill]))[1];
UPDATE runes SET effect = regexp_replace(regexp_replace(regexp_replace(regexp_replace(regexp_replace(regexp_replace(regexp_replace(regexp_replace(regexp_replace(regexp_replace(regexp_replace(regexp_replace(effect, '\ma (Searching)\M', 'an Investigation', 'g'), '\mLore of Ages\M', 'Lore', 'g'), '\mFaiths\M', 'Lore', 'g'), '\mWildlore\M', 'Wildcraft', 'g'), '\mWayfinding\M', 'Wildcraft', 'g'), '\mTumbling\M', 'Agility', 'g'), '\mReading People\M', 'Insight', 'g'), '\mSearching\M', 'Investigation', 'g'), '\mWatchfulness\M', 'Awareness', 'g'), '\mShowcraft\M', 'Performance', 'g'), '\mQuick Hands\M', 'Sleight', 'g'), '\mShadowing\M', 'Stealth', 'g') WHERE effect ~ '\m(Lore of Ages|Faiths|Wildlore|Wayfinding|Tumbling|Reading People|Searching|Watchfulness|Showcraft|Quick Hands|Shadowing)\M';
